CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE clinics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(160) NOT NULL,slug varchar(80) UNIQUE NOT NULL,logo_url text,theme varchar(30) NOT NULL DEFAULT 'terracotta',owner_phone varchar(20),whatsapp_phone varchar(20),email varchar(200),default_slot_minutes int NOT NULL DEFAULT 45,free_customer_cancellations int NOT NULL DEFAULT 2,practitioner_cancel_credit int NOT NULL DEFAULT 1,cancellation_notice_hours int NOT NULL DEFAULT 4,payment_otp_hash varchar(100) NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE branches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinic_id uuid NOT NULL REFERENCES clinics(id),name varchar(120) NOT NULL,address text,timezone varchar(60) NOT NULL DEFAULT 'Asia/Kolkata',opens_at time NOT NULL DEFAULT '09:30',closes_at time NOT NULL DEFAULT '20:00',active boolean NOT NULL DEFAULT true,UNIQUE(clinic_id,name));
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinic_id uuid REFERENCES clinics(id),branch_id uuid REFERENCES branches(id),username varchar(200) UNIQUE NOT NULL,password_hash varchar(100) NOT NULL,display_name varchar(160) NOT NULL,role varchar(30) NOT NULL CHECK(role IN ('PLATFORM_ADMIN','OWNER','RECEPTIONIST','PRACTITIONER')),phone varchar(20),joined_on date,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE services(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinic_id uuid NOT NULL REFERENCES clinics(id),name varchar(160) NOT NULL,category varchar(60) NOT NULL,room_type varchar(40) NOT NULL,minutes int NOT NULL,price numeric(12,2) NOT NULL,discount_percent numeric(5,2) NOT NULL DEFAULT 0,active boolean NOT NULL DEFAULT true,UNIQUE(clinic_id,name));
CREATE TABLE rooms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinic_id uuid NOT NULL REFERENCES clinics(id),branch_id uuid NOT NULL REFERENCES branches(id),name varchar(100) NOT NULL,room_type varchar(40) NOT NULL,active boolean NOT NULL DEFAULT true,UNIQUE(branch_id,name));
CREATE TABLE practitioners(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinic_id uuid NOT NULL REFERENCES clinics(id),user_id uuid REFERENCES users(id),branch_id uuid NOT NULL REFERENCES branches(id),full_name varchar(160) NOT NULL,dob date,joined_on date NOT NULL,engagement varchar(30) NOT NULL,years_experience numeric(4,1) NOT NULL DEFAULT 0,rate numeric(12,2),salary numeric(12,2),photo_url text,document_archive_key text,active boolean NOT NULL DEFAULT true);
CREATE TABLE practitioner_services(practitioner_id uuid REFERENCES practitioners(id),service_id uuid REFERENCES services(id),PRIMARY KEY(practitioner_id,service_id));
CREATE TABLE practitioner_availability(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinic_id uuid NOT NULL REFERENCES clinics(id),practitioner_id uuid NOT NULL REFERENCES practitioners(id),day_of_week int NOT NULL CHECK(day_of_week BETWEEN 1 AND 7),starts_at time NOT NULL,ends_at time NOT NULL);
CREATE TABLE customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinic_id uuid NOT NULL REFERENCES clinics(id),branch_id uuid NOT NULL REFERENCES branches(id),full_name varchar(160) NOT NULL,dob date,phone varchar(20) NOT NULL,email varchar(200),address text,guardian_name varchar(160),guardian_phone varchar(20),joined_on date NOT NULL DEFAULT current_date,free_cancellations_remaining int NOT NULL DEFAULT 2,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customer_services(customer_id uuid REFERENCES customers(id),service_id uuid REFERENCES services(id),PRIMARY KEY(customer_id,service_id));
CREATE TABLE appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinic_id uuid NOT NULL REFERENCES clinics(id),branch_id uuid NOT NULL REFERENCES branches(id),customer_id uuid NOT NULL REFERENCES customers(id),practitioner_id uuid NOT NULL REFERENCES practitioners(id),service_id uuid NOT NULL REFERENCES services(id),room_id uuid NOT NULL REFERENCES rooms(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,status varchar(30) NOT NULL DEFAULT 'BOOKED',price numeric(12,2) NOT NULL,series_id uuid,booked_at timestamptz NOT NULL DEFAULT now(),booked_by uuid REFERENCES users(id),attendance_comment varchar(500),version bigint NOT NULL DEFAULT 0);
CREATE TABLE booking_events(id bigserial PRIMARY KEY,clinic_id uuid NOT NULL REFERENCES clinics(id),appointment_id uuid NOT NULL REFERENCES appointments(id),event_type varchar(40) NOT NULL,actor_user_id uuid REFERENCES users(id),old_values jsonb,new_values jsonb,charge numeric(12,2) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinic_id uuid NOT NULL REFERENCES clinics(id),branch_id uuid NOT NULL REFERENCES branches(id),customer_id uuid NOT NULL REFERENCES customers(id),amount numeric(12,2) NOT NULL,status varchar(30) NOT NULL,method varchar(30),receipt_number varchar(50),receipt_url text,created_at timestamptz NOT NULL DEFAULT now(),confirmed_at timestamptz,confirmed_by uuid REFERENCES users(id));
CREATE TABLE packages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinic_id uuid NOT NULL REFERENCES clinics(id),name varchar(120) NOT NULL,service_id uuid REFERENCES services(id),session_count int NOT NULL,price numeric(12,2) NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE INDEX ix_appointments_capacity ON appointments(clinic_id,branch_id,starts_at,ends_at,status); CREATE INDEX ix_appointments_customer ON appointments(clinic_id,customer_id,starts_at); CREATE INDEX ix_customers_name ON customers(clinic_id,lower(full_name));
